package glitch

import data.glitch_lib

# Helper: check if a conditional chain has a default (a condition with is_default: true)
has_default(conditional) {
    conditional.is_default == true
}

has_default(conditional) {
    not conditional.is_default
    conditional.else_statement != null
    has_default(conditional.else_statement)
}

# Then missing_default is the negation of has_default
missing_default(conditional) {
    not has_default(conditional)
}

Glitch_Analysis[result] {
    # Gather all unit blocks (parents) that have a path (i.e., are in a file)
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    # Get all conditional statements in the parent
    conditionals := glitch_lib.all_conditional_statements(parent)
    top_conditional := conditionals[_]
    # Only top conditionals (that are the head of a chain) and of type IF or SWITCH
    top_conditional.is_top == true
    top_conditional.type in {"IF", "SWITCH"}
    # Check that the chain is missing a default
    missing_default(top_conditional)

    result := {
        "type": "sec_no_default_switch",
        "element": top_conditional,
        "path": parent.path,
        "description": "Missing default case in conditional expression - This could lead to unexpected behavior for unhandled values. (CWE-478)"
    }
}

